"use client";
import Link from 'next/link';import{useState}from'react';import{useRouter}from'next/navigation';import{getSupabaseBrowser}from'../../../lib/supabase/browser';
export default function VendorLogin(){const r=useRouter(),s=getSupabaseBrowser(),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setMsg('');const{error}=await s.auth.signInWithPassword({email,password});if(error)setMsg(error.message);else r.push('/vendor');setBusy(false)}return <main className="page"><style>{css}</style><header><Link href="/" className="brand"><span>IF</span><b>Intelligent Food<small>PROCUREMENT SYSTEM</small></b></Link><Link href="/vendor/register">New vendor? Register →</Link></header><form onSubmit={submit}><label>VENDOR ACCESS</label><h1>Welcome back.</h1><p>Sign in to manage your vendor profile, menus and procurement requests.</p><input required type="email" placeholder="Business email" value={email} onChange={e=>setEmail(e.target.value)}/><input required type="password" placeholder="Password" value={password} onChange={e=>setPassword(e.target.value)}/><button disabled={busy}>{busy?'Signing in…':'Sign in →'}</button>{msg&&<div className="msg">{msg}</div>}<Link href="/vendor/register">Create a vendor account</Link></form></main>}
const css=`body{margin:0;background:#f5f3ee;color:#181813;font-family:Arial}.page{min-height:100vh}.page header{height:78px;background:#faf9f5;border-bottom:1px solid #dedbd2;display:flex;justify-content:space-between;align-items:center;padding:0 7vw}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#181813}.brand span{width:36px;height:36px;border-radius:50%;background:#314d3b;color:#fff;display:grid;place-items:center;font-weight:700}.brand b{font:700 16px Georgia}.brand small{display:block;font:700 7px Arial;letter-spacing:2px;color:#888;margin-top:3px}.page header>a:last-child{font-size:9px;color:#314d3b;text-decoration:none}.page form{max-width:420px;margin:80px auto;background:#faf9f5;border:1px solid #dedbd2;padding:35px;display:grid;gap:11px}.page form label{font-size:8px;letter-spacing:2px;color:#b08b35;font-weight:700}.page h1{font:700 48px Georgia;margin:5px 0}.page p{font-size:10px;color:#777;line-height:1.7}.page input{padding:14px;border:1px solid #dedbd2;background:#fff}.page button{padding:14px;background:#314d3b;color:#fff;border:0;font-size:9px;cursor:pointer}.page button:disabled{opacity:.6}.page form a{font-size:9px;color:#314d3b;text-align:center;text-decoration:none}.msg{font-size:9px;background:#ebe6d8;padding:12px;line-height:1.5}`;
